1	package com.example.starter.rt.service;
2	
3	import java.math.BigDecimal;
4	import java.time.Clock;
5	import java.time.LocalDateTime;
6	import java.util.LinkedHashMap;
7	import java.util.List;
8	import java.util.Map;
9	
10	import org.springframework.dao.DuplicateKeyException;
11	import org.springframework.stereotype.Service;
12	import org.springframework.transaction.annotation.Transactional;
13	
14	import com.example.starter.rt.domain.OperationType;
15	import com.example.starter.rt.domain.PlanStatus;
16	import com.example.starter.rt.dto.ApprovalResponse;
17	import com.example.starter.rt.dto.AuditResponse;
18	import com.example.starter.rt.dto.ClosureResponse;
19	import com.example.starter.rt.dto.ConstraintCheckItem;
20	import com.example.starter.rt.dto.FractionResponse;
21	import com.example.starter.rt.dto.LateFractionResponse;
22	import com.example.starter.rt.dto.RecordedResponse;
23	import com.example.starter.rt.dto.RejectionBody;
24	import com.example.starter.rt.dto.VerificationResponse;
25	import com.example.starter.rt.repository.DirectoryRepository;
26	import com.example.starter.rt.repository.DirectoryRepository.ConstraintItemRow;
27	import com.example.starter.rt.repository.PlanRepository;
28	import com.example.starter.rt.repository.PlanRepository.ActivePlanRow;
29	import com.example.starter.rt.repository.PlanRepository.OarDoseRow;
30	import com.example.starter.rt.repository.PlanRepository.PlanVersionRow;
31	import com.example.starter.rt.repository.WorkflowRepository;
32	import com.example.starter.rt.repository.WorkflowRepository.AuditItemRow;
33	import com.example.starter.rt.repository.WorkflowRepository.AuditRow;
34	import com.example.starter.rt.repository.WorkflowRepository.FractionRow;
35	import com.example.starter.rt.repository.WorkflowRepository.VerificationRow;
36	import com.example.starter.rt.web.ApiException;
37	
38	/**
39	 * 放疗计划核心工作流服务：物理审核→医师批准→首次模体验证→分次执行→疗程结案。
40	 *
41	 * <p>并发控制：涉及患者唯一在执行计划的操作（批准/分次/结案）先对患者主记录加行锁
42	 * （SELECT ... FOR UPDATE），再锁计划版本，锁顺序全局一致（患者→版本）；
43	 * 审核/验证锁计划版本。行锁把同实体并发请求串行化，先提交者写入首次结果，后到者走幂等重放。</p>
44	 *
45	 * <p>所有业务结论（成功 200、业务拒绝 422/409）均以 {@link RecordedResponse} 返回，
46	 * 与业务写库、requestId 幂等记录在同一事务提交；仅资源不存在（404）在进入幂等动作前抛出。</p>
47	 */
48	@Service
49	public class WorkflowService {
50	
51	    private final PlanRepository planRepository;
52	    private final DirectoryRepository directoryRepository;
53	    private final WorkflowRepository workflowRepository;
54	    private final DoseEvaluation doseEvaluation;
55	    private final IdempotencyTemplate idempotency;
56	    private final Clock clock;
57	
58	    public WorkflowService(PlanRepository planRepository, DirectoryRepository directoryRepository,
59	                           WorkflowRepository workflowRepository, DoseEvaluation doseEvaluation,
60	                           IdempotencyTemplate idempotency, Clock clock) {
61	        this.planRepository = planRepository;
62	        this.directoryRepository = directoryRepository;
63	        this.workflowRepository = workflowRepository;
64	        this.doseEvaluation = doseEvaluation;
65	        this.idempotency = idempotency;
66	        this.clock = clock;
67	    }
68	
69	    // ============================ 物理审核 ============================
70	
71	    /** 物理审核：总剂量勾稽 + 约束模板逐项核对（恰等限值合法），任一项超限直接拒绝。 */
72	    @Transactional
73	    public RecordedResponse audit(String patientId, String planCode, int versionNo, String requestId) {
74	        PlanVersionRow version = lockVersion(patientId, planCode, versionNo);
75	        return idempotency.execute(OperationType.AUDIT, requestId,
76	                baseParams(patientId, planCode, versionNo), () -> doAudit(version, requestId));
77	    }
78	
79	    private RecordedResponse doAudit(PlanVersionRow version, String requestId) {
80	        if (!PlanStatus.DESIGN.name().equals(version.status())) {
81	            return reject(422, "PLAN_NOT_IN_DESIGN",
82	                    "计划版本当前状态 " + version.status() + "，仅 DESIGN 状态可提交物理审核");
83	        }
84	        LocalDateTime now = LocalDateTime.now(clock);
85	
86	        boolean totalDoseOk = doseEvaluation.totalDoseMatches(
87	                version.prescribedTotalDoseCgy(), version.fractionDoseCgy(), version.fractionCount());
88	        List<ConstraintItemRow> templateItems =
89	                directoryRepository.findConstraintItems(version.templateCode());
90	        List<OarDoseRow> plannedDoses = planRepository.findOarDoses(version.id());
91	        DoseEvaluation.CheckResult check = doseEvaluation.evaluate(templateItems, plannedDoses);
92	
93	        if (!totalDoseOk || !check.exactCoverageAndWithin()) {
94	            String reason = buildAuditFailureReason(totalDoseOk, check);
95	            return new RecordedResponse(422,
96	                    RejectionBody.withDetails("AUDIT_REJECTED", reason, List.of(check.items().toArray())));
97	        }
98	
99	        long auditId = workflowRepository.insertAudit(version.id(), requestId, true, true, now);
100	        for (ConstraintCheckItem item : check.items()) {
101	            workflowRepository.insertAuditItem(auditId, item.organCode(), item.organName(),
102	                    item.metricType(), item.metricRef(), item.plannedValue(), item.limitValue(),
103	                    item.withinLimit());
104	        }
105	        planRepository.markReviewed(version.id(), now);
106	        AuditResponse response = new AuditResponse(version.id(), version.versionNo(),
107	                PlanStatus.REVIEWED.name(), requestId, false, true, true, check.items());
108	        return new RecordedResponse(200, response);
109	    }
110	
111	    private String buildAuditFailureReason(boolean totalDoseOk, DoseEvaluation.CheckResult check) {
112	        if (!totalDoseOk) {
113	            return "总剂量勾稽不一致：分次剂量×次数≠处方总剂量，审核拒绝";
114	        }
115	        if (!check.missingMetrics().isEmpty()) {
116	            return "申报剂量未覆盖约束模板全部指标项，缺失：" + String.join(",", check.missingMetrics());
117	        }
118	        if (!check.extraMetrics().isEmpty()) {
119	            return "申报剂量存在模板之外的指标项：" + String.join(",", check.extraMetrics());
120	        }
121	        return "存在超过限值的危及器官剂量项（恰等限值合法），审核拒绝";
122	    }
123	
124	    // ============================ 医师批准 ============================
125	
126	    /**
127	     * 医师批准。同一患者同时刻仅一个执行中计划；同计划换版批准时旧版本在本事务内即刻失效。
128	     * 并发批准由患者行锁串行化，唯一成功，其余返回 409。
129	     */
130	    @Transactional
131	    public RecordedResponse approve(String patientId, String planCode, int versionNo, String requestId) {
132	        ensurePatientLock(patientId);
133	        PlanVersionRow version = lockVersion(patientId, planCode, versionNo);
134	        return idempotency.execute(OperationType.APPROVAL, requestId,
135	                baseParams(patientId, planCode, versionNo),
136	                () -> doApprove(patientId, planCode, version, requestId));
137	    }
138	
139	    private RecordedResponse doApprove(String patientId, String planCode, PlanVersionRow version,
140	                                       String requestId) {
141	        if (!PlanStatus.REVIEWED.name().equals(version.status())) {
142	            return reject(422, "PLAN_NOT_REVIEWED",
143	                    "计划版本当前状态 " + version.status() + "，须物理审核通过(REVIEWED)后方可批准");
144	        }
145	        LocalDateTime now = LocalDateTime.now(clock);
146	        ActivePlanRow active = planRepository.findActivePlan(patientId).orElse(null);
147	
148	        if (active == null) {
149	            try {
150	                planRepository.insertActivePlan(patientId, planCode, version.id(), now);
151	            } catch (DuplicateKeyException e) {
152	                return reject(409, "ANOTHER_PLAN_ACTIVE",
153	                        "患者已有执行中计划，同一患者同时刻只允许一个执行中计划");
154	            }
155	        } else if ("CLOSED".equals(active.status())) {
156	            return reject(409, "PATIENT_COURSE_CLOSED",
157	                    "患者疗程已结案（终态），不能再批准执行计划");
158	        } else if (!active.planCode().equals(planCode)) {
159	            return reject(409, "ANOTHER_PLAN_ACTIVE",
160	                    "患者已有执行中计划 " + active.planCode() + "，同一患者同时刻只允许一个执行中计划");
161	        } else if (active.planVersionId() == version.id()) {
162	            return reject(409, "PLAN_ALREADY_APPROVED", "该计划版本已批准，请勿重复批准");
163	        } else {
164	            // 同计划换版：旧版本即刻失效，守卫指向新版本，全部在同一事务内完成，杜绝新旧版本同时可执行。
165	            int invalidated = planRepository.invalidateOtherVersions(
166	                    patientId, planCode, version.id(), now);
167	            int repointed = planRepository.pointActivePlanTo(patientId, planCode, version.id(), now);
168	            if (invalidated == 0 || repointed == 0) {
169	                return reject(409, "PLAN_REVISION_RACE",
170	                        "换版批准并发冲突：旧版本失效或守卫切换未成功");
171	            }
172	        }
173	
174	        planRepository.markApproved(version.id(), now);
175	        ApprovalResponse response = new ApprovalResponse(version.id(), version.versionNo(),
176	                PlanStatus.APPROVED.name(), requestId, false);
177	        return new RecordedResponse(200, response);
178	    }
179	
180	    // ============================ 首次治疗前模体验证 ============================
181	
182	    /** 模体验证：偏差 |实测-计划|/计划×100%，恰 3% 合法，超过 3% 不得执行（失败也留痕形成验证链）。 */
183	    @Transactional
184	    public RecordedResponse verify(String patientId, String planCode, int versionNo,
185	                                   long plannedDoseCgy, long measuredDoseCgy, String requestId) {
186	        PlanVersionRow version = lockVersion(patientId, planCode, versionNo);
187	        Map<String, Object> params = new LinkedHashMap<>(baseParams(patientId, planCode, versionNo));
188	        params.put("plannedDoseCgy", plannedDoseCgy);
189	        params.put("measuredDoseCgy", measuredDoseCgy);
190	        return idempotency.execute(OperationType.VERIFICATION, requestId, params,
191	                () -> doVerify(version, plannedDoseCgy, measuredDoseCgy, requestId));
192	    }
193	
194	    private RecordedResponse doVerify(PlanVersionRow version, long plannedDoseCgy,
195	                                      long measuredDoseCgy, String requestId) {
196	        if (PlanStatus.INVALID.name().equals(version.status())) {
197	            return reject(422, "PLAN_VERSION_INVALID", "该计划版本已失效，不能进行模体验证");
198	        }
199	        if (PlanStatus.DESIGN.name().equals(version.status())
200	                || PlanStatus.REVIEWED.name().equals(version.status())) {
201	            return reject(422, "PLAN_NOT_APPROVED",
202	                    "计划版本当前状态 " + version.status() + "，须医师批准后方可模体验证");
203	        }
204	        if (!PlanStatus.APPROVED.name().equals(version.status())) {
205	            return reject(422, "PLAN_ALREADY_VERIFIED",
206	                    "该计划版本已通过首次模体验证（当前状态 " + version.status() + "），不能重复验证");
207	        }
208	
209	        LocalDateTime now = LocalDateTime.now(clock);
210	        BigDecimal deviation = doseEvaluation.deviationPct(plannedDoseCgy, measuredDoseCgy);
211	        boolean passed = doseEvaluation.deviationWithinLimit(deviation);
212	
213	        // 成功与失败均写入验证链；失败不推进版本状态。
214	        workflowRepository.insertVerification(version.id(), requestId, plannedDoseCgy,
215	                measuredDoseCgy, deviation, passed, now);
216	
217	        if (!passed) {
218	            return reject(422, "VERIFICATION_DEVIATION_EXCEEDED",
219	                    "模体剂量偏差 " + deviation + "% 超过 3% 限值，不得执行首次治疗");
220	        }
221	        planRepository.markVerified(version.id(), now);
222	        VerificationResponse response = new VerificationResponse(version.id(), version.versionNo(),
223	                PlanStatus.VERIFIED.name(), requestId, false, plannedDoseCgy, measuredDoseCgy,
224	                deviation, true);
225	        return new RecordedResponse(200, response);
226	    }
227	
228	    // ============================ 分次执行 ============================
229	
230	    /**
231	     * 分次执行记录。按“患者＋计划＋分次号”去重；分次号必须为当前台账数+1，跳次拒绝并告警；
232	     * 疗程结案后的迟到分次仅登记迟到事件。
233	     */
234	    @Transactional
235	    public RecordedResponse recordFraction(String patientId, String planCode, int fractionNo,
236	                                           long deliveredDoseCgy, String requestId) {
237	        ensurePatientLock(patientId);
238	        Map<String, Object> params = new LinkedHashMap<>();
239	        params.put("patientId", patientId);
240	        params.put("planCode", planCode);
241	        params.put("fractionNo", fractionNo);
242	        params.put("deliveredDoseCgy", deliveredDoseCgy);
243	        return idempotency.execute(OperationType.FRACTION, requestId, params,
244	                () -> doRecordFraction(patientId, planCode, fractionNo, deliveredDoseCgy, requestId));
245	    }
246	
247	    private RecordedResponse doRecordFraction(String patientId, String planCode, int fractionNo,
248	                                              long deliveredDoseCgy, String requestId) {
249	        LocalDateTime now = LocalDateTime.now(clock);
250	        ActivePlanRow active = planRepository.findActivePlan(patientId).orElse(null);
251	
252	        if (active == null) {
253	            return reject(422, "NO_ACTIVE_PLAN", "患者不存在执行中计划，不能登记分次");
254	        }
255	        if ("CLOSED".equals(active.status())) {
256	            // 结案终态：迟到分次只登记迟到事件，不计入台账、不执行投递。归属到实际结案的计划版本。
257	            String closedPlanCode = active.planCode();
258	            PlanVersionRow closedVersion = planRepository.findVersionById(active.planVersionId())
259	                    .orElseThrow(() -> ApiException.notFound("PLAN_VERSION_NOT_FOUND", "结案版本不存在"));
260	            try {
261	                workflowRepository.insertLateFraction(patientId, closedPlanCode, closedVersion.id(),
262	                        fractionNo, requestId, now);
263	            } catch (DuplicateKeyException e) {
264	                return reject(409, "LATE_EVENT_DUPLICATE", "迟到分次事件 requestId 已存在：" + requestId);
265	            }
266	            LateFractionResponse response = new LateFractionResponse(
267	                    "LATE_EVENT_RECORDED", patientId, closedPlanCode, closedVersion.id(),
268	                    closedVersion.versionNo(), fractionNo, requestId, false, Responses.odt(now));
269	            return new RecordedResponse(200, response);
270	        }
271	        if (!active.planCode().equals(planCode)) {
272	            return reject(409, "ANOTHER_PLAN_ACTIVE",
273	                    "患者当前执行中计划为 " + active.planCode() + "，与请求计划 " + planCode + " 不一致");
274	        }
275	
276	        PlanVersionRow version = planRepository.lockVersionById(active.planVersionId())
277	                .orElseThrow(() -> ApiException.notFound("PLAN_VERSION_NOT_FOUND", "执行中计划版本不存在"));
278	        if (PlanStatus.INVALID.name().equals(version.status())
279	                || PlanStatus.CLOSED.name().equals(version.status())) {
280	            return reject(422, "PLAN_VERSION_NOT_EXECUTABLE",
281	                    "计划版本当前状态 " + version.status() + "，不能登记分次");
282	        }
283	        if (!PlanStatus.VERIFIED.name().equals(version.status())
284	                && !PlanStatus.EXECUTING.name().equals(version.status())) {
285	            return reject(422, "FIRST_VERIFICATION_REQUIRED",
286	                    "首次治疗前必须通过模体验证（当前状态 " + version.status() + "），不得执行分次");
287	        }
288	
289	        int recorded = workflowRepository.countFractions(patientId, planCode);
290	        int expected = recorded + 1;
291	        if (fractionNo < expected) {
292	            // 自然键去重：与 requestId 幂等相互独立，重复分次号直接拒绝，不产生新记录。
293	            return reject(409, "FRACTION_ALREADY_RECORDED",
294	                    "分次 " + fractionNo + " 已存在，按患者+计划+分次号去重，拒绝重复登记");
295	        }
296	        if (fractionNo > expected) {
297	            // 跳次：拒绝且告警（alert=true）。
298	            return new RecordedResponse(409, RejectionBody.alert("FRACTION_SKIP_DETECTED",
299	                    "跳次执行：下一分次应为第 " + expected + " 次，请求第 " + fractionNo
300	                            + " 次，拒绝并告警"));
301	        }
302	
303	        long fractionId;
304	        try {
305	            fractionId = workflowRepository.insertFraction(patientId, planCode, version.id(),
306	                    fractionNo, deliveredDoseCgy, requestId, now);
307	        } catch (DuplicateKeyException e) {
308	            return reject(409, "FRACTION_ALREADY_RECORDED",
309	                    "分次 " + fractionNo + " 已存在（并发去重），拒绝重复登记");
310	        }
311	        planRepository.markExecutingIfFirst(version.id(), now);
312	
313	        FractionResponse response = new FractionResponse(fractionId, patientId, planCode,
314	                version.id(), version.versionNo(), fractionNo, deliveredDoseCgy, requestId,
315	                false, Responses.odt(now));
316	        return new RecordedResponse(200, response);
317	    }
318	
319	    // ============================ 疗程结案 ============================
320	
321	    /** 疗程结案（终态）。重复结案返回幂等成功；结案后迟到分次只登记迟到事件。 */
322	    @Transactional
323	    public RecordedResponse close(String patientId, String planCode, String requestId) {
324	        ensurePatientLock(patientId);
325	        Map<String, Object> params = new LinkedHashMap<>();
326	        params.put("patientId", patientId);
327	        params.put("planCode", planCode);
328	        return idempotency.execute(OperationType.CLOSURE, requestId, params,
329	                () -> doClose(patientId, planCode, requestId));
330	    }
331	
332	    private RecordedResponse doClose(String patientId, String planCode, String requestId) {
333	        LocalDateTime now = LocalDateTime.now(clock);
334	        ActivePlanRow active = planRepository.findActivePlan(patientId).orElse(null);
335	        if (active == null) {
336	            return reject(422, "NO_ACTIVE_PLAN", "患者不存在已批准计划，不能结案");
337	        }
338	        if ("CLOSED".equals(active.status())) {
339	            // 终态重复结案：无论是否同 requestId，均返回幂等成功。
340	            PlanVersionRow closedVersion = planRepository.findVersionById(active.planVersionId())
341	                    .orElseThrow(() -> ApiException.notFound("PLAN_VERSION_NOT_FOUND", "结案版本不存在"));
342	            ClosureResponse response = new ClosureResponse(closedVersion.id(),
343	                    closedVersion.versionNo(), PlanStatus.CLOSED.name(), requestId, true);
344	            return new RecordedResponse(200, response);
345	        }
346	        if (!active.planCode().equals(planCode)) {
347	            return reject(409, "ANOTHER_PLAN_ACTIVE",
348	                    "患者当前执行中计划为 " + active.planCode() + "，不能对计划 " + planCode + " 结案");
349	        }
350	
351	        PlanVersionRow version = planRepository.lockVersionById(active.planVersionId()).orElseThrow();
352	        planRepository.markClosed(version.id(), now);
353	        planRepository.closeActivePlan(patientId, now);
354	        ClosureResponse response = new ClosureResponse(version.id(), version.versionNo(),
355	                PlanStatus.CLOSED.name(), requestId, false);
356	        return new RecordedResponse(200, response);
357	    }
358	
359	    // ============================ 复算与台账查询 ============================
360	
361	    /** 物理审核复算：按模板限值与申报值实时复算逐项结果，并与审核通过时的存储快照逐项对比。 */
362	    @Transactional(readOnly = true)
363	    public AuditRecomputation recomputeAudit(String patientId, String planCode, int versionNo) {
364	        PlanVersionRow version = getVersion(patientId, planCode, versionNo);
365	        List<ConstraintItemRow> templateItems =
366	                directoryRepository.findConstraintItems(version.templateCode());
367	        List<OarDoseRow> plannedDoses = planRepository.findOarDoses(version.id());
368	        DoseEvaluation.CheckResult recomputed = doseEvaluation.evaluate(templateItems, plannedDoses);
369	
370	        AuditRow auditRow = workflowRepository.findAuditByVersion(version.id()).orElse(null);
371	        List<AuditItemRow> storedItems = auditRow == null
372	                ? List.of()
373	                : workflowRepository.findAuditItems(auditRow.id());
374	        boolean matchesSnapshot = auditRow != null && snapshotMatches(storedItems, recomputed.items());
375	        return new AuditRecomputation(version, auditRow != null, recomputed.items(),
376	                storedItems.size(), matchesSnapshot);
377	    }
378	
379	    private boolean snapshotMatches(List<AuditItemRow> stored, List<ConstraintCheckItem> recomputed) {
380	        if (stored.size() != recomputed.size()) {
381	            return false;
382	        }
383	        for (int i = 0; i < stored.size(); i++) {
384	            AuditItemRow s = stored.get(i);
385	            ConstraintCheckItem r = recomputed.get(i);
386	            if (!s.organCode().equals(r.organCode())
387	                    || !s.metricType().equals(r.metricType())
388	                    || s.withinLimit() != r.withinLimit()
389	                    || s.plannedValue().compareTo(r.plannedValue()) != 0
390	                    || s.limitValue().compareTo(r.limitValue()) != 0) {
391	                return false;
392	            }
393	        }
394	        return true;
395	    }
396	
397	    /** 模体验证链（含失败记录）。 */
398	    @Transactional(readOnly = true)
399	    public List<VerificationRow> verificationChain(String patientId, String planCode, int versionNo) {
400	        PlanVersionRow version = getVersion(patientId, planCode, versionNo);
401	        return workflowRepository.findVerifications(version.id());
402	    }
403	
404	    /** 分次台账（按分次号升序，同计划跨版本连续编号）。 */
405	    @Transactional(readOnly = true)
406	    public List<FractionRow> fractionLedger(String patientId, String planCode) {
407	        return workflowRepository.findFractions(patientId, planCode);
408	    }
409	
410	    /** 结案后迟到分次事件列表。 */
411	    @Transactional(readOnly = true)
412	    public List<WorkflowRepository.LateFractionRow> lateFractions(String patientId, String planCode) {
413	        return workflowRepository.findLateFractions(patientId, planCode);
414	    }
415	
416	    /** 计划全部版本视图。 */
417	    @Transactional(readOnly = true)
418	    public List<PlanVersionRow> versions(String patientId, String planCode) {
419	        return planRepository.findVersions(patientId, planCode);
420	    }
421	
422	    // ============================ 内部辅助 ============================
423	
424	    private RecordedResponse reject(int httpStatus, String code, String message) {
425	        boolean alert = "FRACTION_SKIP_DETECTED".equals(code);
426	        return new RecordedResponse(httpStatus, new RejectionBody(code, message, alert, List.of()));
427	    }
428	
429	    private Map<String, Object> baseParams(String patientId, String planCode, int versionNo) {
430	        Map<String, Object> params = new LinkedHashMap<>();
431	        params.put("patientId", patientId);
432	        params.put("planCode", planCode);
433	        params.put("versionNo", versionNo);
434	        return params;
435	    }
436	
437	    private void ensurePatientLock(String patientId) {
438	        if (!planRepository.lockPatient(patientId)) {
439	            throw ApiException.notFound("PATIENT_NOT_FOUND", "患者不存在：" + patientId);
440	        }
441	    }
442	
443	    private PlanVersionRow lockVersion(String patientId, String planCode, int versionNo) {
444	        return planRepository.lockVersion(patientId, planCode, versionNo)
445	                .orElseThrow(() -> ApiException.notFound("PLAN_VERSION_NOT_FOUND",
446	                        "计划版本不存在：" + planCode + "#v" + versionNo));
447	    }
448	
449	    private PlanVersionRow getVersion(String patientId, String planCode, int versionNo) {
450	        return planRepository.findVersion(patientId, planCode, versionNo)
451	                .orElseThrow(() -> ApiException.notFound("PLAN_VERSION_NOT_FOUND",
452	                        "计划版本不存在：" + planCode + "#v" + versionNo));
453	    }
454	
455	    /** 审核复算聚合结果。 */
456	    public record AuditRecomputation(
457	            PlanVersionRow version,
458	            boolean auditStored,
459	            List<ConstraintCheckItem> recomputedItems,
460	            int storedItemCount,
461	            boolean snapshotMatches) {
462	    }
463	}
