    public RadiotherapyController(PlanAdminService adminService, WorkflowService workflowService) {
        this.adminService = adminService;
        this.workflowService = workflowService;
    }

    // ---------------- 合成目录与计划设计 ----------------

    @PostMapping("/patients")
