322	                (rs, n) -> rs.getString(1), patientId);
323	        return !locked.isEmpty();
324	    }
325	
326	    /** 仅用于测试清理：清空全部业务表并重置自增。 */
327	    public void deleteAllForTest() {
328	        jdbc.execute("DELETE FROM idempotent_request");
329	        jdbc.execute("DELETE FROM late_fraction_event");
330	        jdbc.execute("DELETE FROM fraction_execution");
331	        jdbc.execute("DELETE FROM verification");
332	        jdbc.execute("DELETE FROM physics_audit_item");
333	        jdbc.execute("DELETE FROM physics_audit");
334	        jdbc.execute("DELETE FROM plan_oar_dose");
335	        jdbc.execute("DELETE FROM plan_version");
336	        jdbc.execute("DELETE FROM patient_active_plan");
337	        jdbc.execute("DELETE FROM constraint_item");
338	        jdbc.execute("DELETE FROM constraint_template");
339	        jdbc.execute("DELETE FROM patient");
340	        jdbc.execute("ALTER TABLE plan_version ALTER COLUMN id RESTART WITH 1");
341	        jdbc.execute("ALTER TABLE plan_oar_dose ALTER COLUMN id RESTART WITH 1");
342	        jdbc.execute("ALTER TABLE physics_audit ALTER COLUMN id RESTART WITH 1");
343	        jdbc.execute("ALTER TABLE physics_audit_item ALTER COLUMN id RESTART WITH 1");
344	        jdbc.execute("ALTER TABLE verification ALTER COLUMN id RESTART WITH 1");
345	        jdbc.execute("ALTER TABLE fraction_execution ALTER COLUMN id RESTART WITH 1");
346	        jdbc.execute("ALTER TABLE late_fraction_event ALTER COLUMN id RESTART WITH 1");
347	    }
348	}
