22	
23	/**
24	 * 合成目录与计划设计服务：建档患者、约束模板，创建计划新版本（DESIGN）。
25	 */
26	@Service
27	public class PlanAdminService {
28	
29	    private final DirectoryRepository directory;
30	    private final PlanRepository planRepository;
31	    private final Clock clock;
32	
33	    public PlanAdminService(DirectoryRepository directory, PlanRepository planRepository, Clock clock) {
34	        this.directory = directory;
35	        this.planRepository = planRepository;
36	        this.clock = clock;
37	    }
38	
39	    /** 新建合成患者；同 ID 重复创建返回 409。 */
40	    @Transactional
41	    public void createPatient(CreatePatientRequest request) {
42	        try {
43	            boolean inserted = directory.insertPatient(
44	                    request.patientId(), request.patientName(), LocalDateTime.now(clock));
45	            if (!inserted) {
46	                throw ApiException.conflict("PATIENT_EXISTS", "患者已存在：" + request.patientId());
47	            }
48	        } catch (DuplicateKeyException e) {
49	            throw ApiException.conflict("PATIENT_EXISTS", "患者已存在：" + request.patientId());
50	        }
51	    }
52	
53	    /** 新建约束模板及逐项限值。 */
54	    @Transactional
55	    public void createTemplate(CreateTemplateRequest request) {
56	        validateTemplateItems(request.items());
57	        try {
58	            boolean inserted = directory.insertTemplate(
59	                    request.templateCode(), request.templateName(), LocalDateTime.now(clock));
60	            if (!inserted) {
61	                throw ApiException.conflict("TEMPLATE_EXISTS", "约束模板已存在：" + request.templateCode());
62	            }
63	        } catch (DuplicateKeyException e) {
64	            throw ApiException.conflict("TEMPLATE_EXISTS", "约束模板已存在：" + request.templateCode());
65	        }
66	        for (ConstraintItemRequest item : request.items()) {
67	            directory.insertConstraintItem(request.templateCode(), item.organCode(), item.organName(),
68	                    item.metricType().name(), item.metricRef(), item.limitValue());
69	        }
70	    }
71	
72	    /** 创建计划新版本（同 planCode 再次调用即换版，新版本为 DESIGN，旧版在重新批准的同一事务失效）。 */
73	    @Transactional
74	    public PlanVersionResponse createPlan(CreatePlanRequest request) {
75	        if (!directory.patientExists(request.patientId())) {
76	            throw ApiException.notFound("PATIENT_NOT_FOUND", "患者不存在：" + request.patientId());
77	        }
78	        if (!directory.templateExists(request.templateCode())) {
79	            throw ApiException.notFound("TEMPLATE_NOT_FOUND", "约束模板不存在：" + request.templateCode());
80	        }
81	        validateOarDoses(request.oarDoses());
