        Instant start = Instant.now().plus(2, ChronoUnit.HOURS).truncatedTo(ChronoUnit.SECONDS);

        // 400：窗口长度 15 分钟 ≠ 等级1的10分钟
        ResponseEntity<Map> badWindow = post("/schedules",
